239→/// Build a batch INSERT for `raw_transactions` with ON CONFLICT DO NOTHING.
240→pub fn build_raw_transaction_insert(
241→    txs: &[RawTransaction],
242→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
243→    let mut query = String::from(
244→        "INSERT INTO raw_transactions \
245→         (id, network, tx_hash, timestamp, block_number, raw_metadata, source, ingestion_run_id, ingested_at) \
246→         VALUES ",
247→    );
248→    let mut args = sqlx::postgres::PgArguments::default();
249→    for (i, tx) in txs.iter().enumerate() {
250→        let base = i * 9;
251→        if i > 0 {
252→            query.push_str(", ");
253→        }
254→        query.push_str(&format!(
255→            "(${}, ${}, ${}, ${}, ${}, ${}, ${}, ${}, ${})",
256→            base + 1,
257→            base + 2,
258→            base + 3,
259→            base + 4,
260→            base + 5,
261→            base + 6,
262→            base + 7,
263→            base + 8,
264→            base + 9,
265→        ));
266→        use sqlx::Arguments;
267→        args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
268→        args.add(&tx.network).map_err(|e| anyhow::anyhow!("{e}"))?;
269→        args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
270→        args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
271→        args.add(tx.block_number)
272→            .map_err(|e| anyhow::anyhow!("{e}"))?;
273→        args.add(&tx.raw_metadata)
274→            .map_err(|e| anyhow::anyhow!("{e}"))?;
275→        args.add(&tx.source).map_err(|e| anyhow::anyhow!("{e}"))?;
276→        args.add(tx.ingestion_run_id)
277→            .map_err(|e| anyhow::anyhow!("{e}"))?;
278→        args.add(tx.ingested_at)
279→            .map_err(|e| anyhow::anyhow!("{e}"))?;
280→    }
281→    query.push_str(" ON CONFLICT (network, tx_hash) DO NOTHING");
282→    Ok((query, args))
283→}
