424→async fn trigger_ingest(
425→    State(state): State<Arc<AppState>>,
426→    Json(payload): Json<IngestRequest>,
427→) -> Result<Json<JobStatus>, AppError> {
428→    validate_wallet(&payload.wallet)?;
429→    check_wallet_allowed(&payload.wallet, &state.allowed_wallets)?;
430→    if let Some(ref url) = payload.callback_url {
431→        validate_callback_url(url)?;
432→    }
433→
434→    let chain = payload.chain.clone();
435→    match chain.as_str() {
436→        "solana" | "ethereum" | "hyperliquid" => {}
437→        other => {
438→            return Err(AppError::bad_request(format!(
439→                "Unsupported chain: {other}. Supported chains: solana, ethereum, hyperliquid"
440→            )));
441→        }
442→    }
443→
444→    let permit = state
445→        .job_semaphore
446→        .clone()
447→        .try_acquire_owned()
448→        .map_err(|_| AppError::service_unavailable("Too many concurrent jobs"))?;
449→
450→    let job_id = Uuid::new_v4();
451→    let job = JobStatus {
452→        id: job_id,
453→        state: JobState::Pending,
454→        message: None,
455→    };
456→
457→    state.jobs.write().await.insert(
458→        job_id,
459→        JobEntry {
460→            status: job.clone(),
461→            finished_at: None,
462→        },
463→    );
464→
465→    let state_clone = Arc::clone(&state);
466→    let wallet = payload.wallet.clone();
467→    let callback_url = payload.callback_url.clone();
468→    let limit = state.config.ingest_limit;
469→    let user_id = payload.user_id.unwrap_or_else(Uuid::new_v4);
470→
471→    tokio::spawn(async move {
472→        let _permit = permit;
473→        {
474→            let mut jobs = state_clone.jobs.write().await;
475→            if let Some(entry) = jobs.get_mut(&job_id) {
476→                entry.status.state = JobState::Running;
477→            } else {
478→                warn!(job_id = %job_id, "Job entry missing when setting running state");
479→            }
480→        }
481→
482→        let result = async {
483→            let checkpoint: Option<IndexerCheckpoint> = state_clone
484→                .repo
485→                .get_checkpoint(&chain, &wallet)
486→                .await
487→                .unwrap_or(None);
488→
489→            // Parse chain enum for ensure_wallet_target
490→            let chain_enum = match chain.as_str() {
491→                "solana" => Chain::Solana,
492→                "ethereum" => Chain::Ethereum,
493→                "hyperliquid" => Chain::Hyperliquid,
494→                _ => unreachable!("chain validated before spawn"),
495→            };
496→
497→            // Ensure a V2 IndexTarget exists for this wallet (best-effort)
498→            let target_id = match state_clone
499→                .repo
500→                .ensure_wallet_target(&chain_enum, &wallet, Some(user_id))
501→                .await
502→            {
503→                Ok(target) => Some(target.id),
504→                Err(e) => {
505→                    warn!(
506→                        error = %e,
507→                        wallet = %wallet,
508→                        "Failed to ensure V2 wallet target (V1 path unaffected)"
509→                    );
510→                    None
511→                }
512→            };
513→
514→            let events: Vec<Transaction> = match chain.as_str() {
515→                "hyperliquid" => {
516→                    let adapter = HyperliquidAdapter::new();
517→                    adapter
518→                        .fetch_history(&wallet, limit, user_id, checkpoint.as_ref())
519→                        .await?
520→                }
521→                "ethereum" => {
522→                    let adapter = EvmAdapter::new(&state_clone.config.evm_rpc_url)?;
523→                    adapter
524→                        .fetch_history(&wallet, limit, user_id, checkpoint.as_ref())
525→                        .await?
526→                }
527→                "solana" => {
528→                    let adapter = SolanaAdapter::new(&state_clone.config.solana_rpc_url);
529→                    adapter
530→                        .fetch_history(&wallet, limit, user_id, checkpoint.as_ref())
531→                        .await?
532→                }
533→                _ => unreachable!("chain validated before spawn"),
534→            };
535→            let count = events.len();
536→            if let Some(cp) = build_checkpoint(&chain, &wallet, &events) {
537→                if let Some(tid) = target_id {
538→                    state_clone
539→                        .repo
540→                        .save_transactions_and_checkpoint_dual_write(&events, &cp, tid)
541→                        .await?;
542→                } else {
543→                    state_clone
544→                        .repo
545→                        .save_transactions_and_checkpoint(&events, &cp)
546→                        .await?;
547→                }
548→            } else if let Some(tid) = target_id {
549→                state_clone
550→                    .repo
551→                    .save_transactions_dual_write(&events, tid)
552→                    .await?;
553→            } else {
554→                state_clone.repo.save_transactions(&events).await?;
555→            }
556→            Ok::<usize, anyhow::Error>(count)
557→        }
558→        .await;
559→
560→        let (final_state, final_message) = {
561→            let mut jobs = state_clone.jobs.write().await;
562→            if let Some(entry) = jobs.get_mut(&job_id) {
563→                match result {
564→                    Ok(count) => {
565→                        info!(job_id = %job_id, count, "Ingestion completed");
566→                        entry.status.state = JobState::Completed;
567→                        entry.status.message = Some(format!("Ingested {} transactions", count));
568→                    }
569→                    Err(e) => {
570→                        error!(job_id = %job_id, error = %e, "Ingestion failed");
571→                        entry.status.state = JobState::Failed;
572→                        entry.status.message = Some(e.to_string());
573→                    }
574→                }
575→                entry.finished_at = Some(Instant::now());
576→                let s = serde_json::to_value(&entry.status.state).ok();
577→                let m = entry.status.message.clone();
578→                (s, m)
579→            } else {
580→                (None, None)
581→            }
582→        };
583→
584→        if let Some(ref url) = callback_url {
585→            let payload = serde_json::json!({
586→                "job_id": job_id,
587→                "state": final_state,
588→                "wallet": wallet,
589→                "chain": chain,
590→                "message": final_message,
591→            });
592→            fire_callback(url, &payload).await;
593→        }
594→
595→        state_clone.prune_stale_jobs().await;
596→    });
597→
598→    info!(job_id = %job_id, "Ingestion job queued");
599→    Ok(Json(JobStatus {
600→        id: job_id,
601→        state: JobState::Pending,
602→        message: Some("Job queued".to_string()),
603→    }))
604→}
