606→const MAX_BATCH_SIZE: usize = 50;
607→
608→async fn trigger_batch_ingest(
609→    State(state): State<Arc<AppState>>,
610→    Json(payload): Json<BatchIngestRequest>,
611→) -> Result<Json<Vec<JobStatus>>, AppError> {
612→    if payload.wallets.is_empty() {
613→        return Err(AppError::bad_request("wallets array must not be empty"));
614→    }
615→    if payload.wallets.len() > MAX_BATCH_SIZE {
616→        return Err(AppError::bad_request(format!(
617→            "batch size {} exceeds maximum of {MAX_BATCH_SIZE}",
618→            payload.wallets.len()
619→        )));
620→    }
621→
622→    for item in &payload.wallets {
623→        validate_wallet(&item.wallet)?;
624→        check_wallet_allowed(&item.wallet, &state.allowed_wallets)?;
625→        match item.chain.as_str() {
626→            "solana" | "ethereum" | "hyperliquid" => {}
627→            other => {
628→                return Err(AppError::bad_request(format!(
629→                    "Unsupported chain: {other}. Supported chains: solana, ethereum, hyperliquid"
630→                )));
631→            }
632→        }
633→    }
634→
635→    let mut jobs = Vec::with_capacity(payload.wallets.len());
636→    for item in payload.wallets {
637→        let single = Json(IngestRequest {
638→            chain: item.chain,
639→            wallet: item.wallet,
640→            user_id: item.user_id,
641→            callback_url: item.callback_url,
642→        });
643→        match trigger_ingest(State(Arc::clone(&state)), single).await {
644→            Ok(Json(status)) => jobs.push(status),
645→            Err(e) if e.status == StatusCode::SERVICE_UNAVAILABLE => {
646→                return Err(AppError::service_unavailable(format!(
647→                    "Concurrency limit reached after queuing {} of {} jobs",
648→                    jobs.len(),
649→                    jobs.len() + 1
650→                )));
651→            }
652→            Err(e) => return Err(e),
653→        }
654→    }
655→
656→    Ok(Json(jobs))
657→}
