1061→
1062→        if !batch.is_empty() {
1063→            if let Err(e) = repo.save_transactions(&batch).await {
1064→                error!(stream_id = %stream_id, error = %e, "Failed to flush final batch");
1065→            }
1066→        }
1067→
1068→        grpc_handle.abort();
1069→        state_clone.streams.write().await.remove(&stream_id);
1070→        info!(stream_id = %stream_id, "Stream removed from active set");
1071→    });
1072→
1073→    let entry = StreamEntry {
1074→        id: stream_id,
1075→        cancel: cancel.clone(),
1076→        started_at: Instant::now(),
1077→        tx_count: Arc::clone(&tx_count),
1078→        last_slot: Arc::clone(&last_slot),
1079→    };
1080→
1081→    let info = StreamInfo {
1082→        id: stream_id,
1083→        uptime_secs: 0,
1084→        transactions_ingested: 0,
1085→        last_slot: 0,
1086→    };
1087→
1088→    state.streams.write().await.insert(stream_id, entry);
1089→    info!(stream_id = %stream_id, "Stream started");
1090→
1091→    Ok(Json(info))
1092→}
