1156→async fn register_target(
1157→    State(state): State<Arc<AppState>>,
1158→    Json(req): Json<RegisterTargetRequest>,
1159→) -> Result<(StatusCode, Json<IndexTarget>), AppError> {
1160→    // Parse kind
1161→    let kind: TargetKind = req
1162→        .kind
1163→        .parse()
1164→        .map_err(|_| AppError::bad_request(format!("Invalid target kind: {}", req.kind)))?;
1165→
1166→    // Parse mode (default to "both")
1167→    let mode_str = req.mode.as_deref().unwrap_or("both");
1168→    let mode: TargetMode = mode_str
1169→        .parse()
1170→        .map_err(|_| AppError::bad_request(format!("Invalid mode: {mode_str}")))?;
1171→
1172→    // Look up network
1173→    let network = state
1174→        .repo
1175→        .get_network(&req.network)
1176→        .await
1177→        .map_err(AppError::internal)?
1178→        .ok_or_else(|| AppError::bad_request(format!("Unknown network: {}", req.network)))?;
1179→
1180→    // Normalize address
1181→    let address = req.address.map(|addr| match network.chain_family {
1182→        ChainFamily::Evm | ChainFamily::Hyperliquid => normalize_evm_address(&addr),
1183→        ChainFamily::Solana => normalize_solana_address(&addr),
1184→    });
1185→
1186→    let now = chrono::Utc::now();
1187→    let target = IndexTarget {
1188→        id: Uuid::new_v4(),
1189→        kind,
1190→        network: req.network,
1191→        chain_family: network.chain_family,
1192→        address,
1193→        filter_spec: req.filter_spec,
1194→        mode,
1195→        label: req.label,
1196→        owner_id: None,
1197→        created_at: now,
1198→        updated_at: now,
1199→    };
1200→
1201→    // Validate
1202→    if let Err(errors) = validate_target(&target) {
1203→        return Err(AppError::bad_request(errors.join("; ")));
1204→    }
1205→
1206→    // Persist
1207→    match state.repo.create_index_target(&target).await {
1208→        Ok(created) => Ok((StatusCode::CREATED, Json(created))),
1209→        Err(e) => {
1210→            let msg = e.to_string();
1211→            if msg.contains("duplicate key") || msg.contains("unique constraint") {
1212→                Err(conflict(
1213→                    "A target with the same kind, network, and address already exists",
1214→                ))
1215→            } else {
1216→                Err(AppError::internal(e))
1217→            }
1218→        }
1219→    }
1220→}
