fn row_to_ingestion_run(row: &sqlx::postgres::PgRow) -> anyhow::Result<IngestionRun> {
    Ok(IngestionRun {
        id: row.try_get("id")?,
        target_id: row.try_get("target_id")?,
        network: row.try_get("network")?,
        source: row.try_get("source")?,
