            },
        );
        state.jobs.write().await.insert(
            new_id,
            JobEntry {
                status: JobStatus {
                    id: new_id,
                    state: JobState::Running,
                    message: None,
                },
                finished_at: None,
            },
        );

        state.prune_stale_jobs().await;

